            angle={-45}
            textAnchor="end"
            height={60}
            tick={{ fontSize: 12 }}
          />
          <YAxis domain={["auto", "auto"]} tick={{ fontSize: 12 }} />
          <RechartsTooltip
            labelFormatter={(value) => {
              if (typeof value === "number") {
                return formatChartDate(new Date(value).toISOString()).display;
              }
              return value;
            }}
          />
          <Legend />
          <Line
            type="monotone"
            dataKey={label}
            stroke={CHART_COLORS[0]}
            dot={true}
            connectNulls
          />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

