  () => (abnormalOnly ? rows.filter((row) => row.hasAbnormal) : rows),
  [abnormalOnly, rows],
);

if (isLoading || !data) {
  return <Loading />;
}

if (days.length === 0) {
  return (
    <div className="flex h-24 items-center justify-center text-sm text-gray-500">
      {t("no_data_available")}
    </div>
  );
}

